package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaHaDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Ganin Farkon 'Ya'yan itace", "Ya Allah ka albarkace mu a cikin 'ya'yan itacenmu, ka albarkace mu a garinmu, kuma ka albarkace mu a cikin sa'o'inmu da laka (ma'auni).", "A kan ganin 'ya'yan itace na farko na kakar.", "Addu'ar albarka a cikin arziki da kuma a cikin mutum."),
        "dua_good_news" to DuaText("Bayan Labari Mai Dadi", "Dukkan godiya ta tabbata ga Allah, wanda da ni'imarSa aka cika kyawawan abubuwa.", "Akan karbar bushara (kuma kayi sujjadar godiya).", "Annabi ﷺ ya fadi haka akan yaga abinda yake so."),
        "dua_looking_mirror" to DuaText("Kallon cikin Madubin", "Ya Allah kamar yadda ka kyautata min kamanni, nima ka kyautata halina.", "Lokacin kallon madubi.", "Annabi ﷺ yayi wannan dua (ana kafa ta ko da ba a ambaci madubi ba)."),
        "dua_rabbana_taqabbal" to DuaText("Karbar Ayyuka", "Ya Ubangijinmu, Ka karɓi wannan daga gare mu; Lalle ne Kai, Kai ne Mai ji, Masani. Kuma ka karbi tubanmu; Lalle ne Kai, Kai ne Mai karɓar tũba, Mai jin ƙai.", "An tambayi Ibrahim da Isma'il (AS) a lokacin gina Ka'aba.", "Addu'a don karbuwa bayan kowane aikin alheri."),
        "dua_muawwidhat" to DuaText("Quls Uku (Mu'awwidhat)", "(Suratul Ikhlas) Ka ce: \"Shi ne Allah Makaɗaici.\" Allah, Mawadaci. Ba ya haihuwa kuma ba ya haihuwa. Kuma babu wani misãli a gare Shi.\n\n(Suratul Falaq) Ka ce: “Ina neman tsarin Ubangijin safiya, da sharrin abin da Ya halitta, da sharrin duhu idan ya tsaya, da sharrin masu busa kulli, da sharrin mai hassada idan ya yi hassada.\n\n(Suratul Nas) Ka ce: “Ina neman tsari da Ubangijin mutane, Sarkin mutane, Ubangijin mutane, daga sharrin mai yin waswasi mai ja da baya, mai sanya waswasi a cikin zukatan mutane, daga aljannu da mutane.", "Surorin guda uku sau uku safe da yamma, sannan kafin barci sai a hura hannaye a shafa a jiki.", "Karanta su sau uku safe da yamma ya wadatar da komai."),
        "dua_sabr" to DuaText("Domin Hakuri da Juriya", "Ya Ubangijinmu Ka zuba mana haƙuri, kuma Ka tabbatar da ƙafãfunmu, kuma Ka taimake mu a kan mutãnen nan kãfirai.", "A lokacin wahala da fuskantar.", "Addu'ar sojojin Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Gafara da Kariya daga Wuta", "Ya Ubangijinmu, mun yi imani, don haka Ka gafarta mana zunubanmu, kuma Ka tsare mu daga azabar wuta.", "A Qur'ani dua.", "Addu'a da aka ambata cikin halayen masu tsoron Allah."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Shiriya A Cikin Al'amarin Mu (Ashab al-Kahf)", "Ya Ubangijinmu!", "Addu'ar Mutanen Kogo.", "Jagoranci a cikin yanke shawara da yanayi masu wuyar gaske."),
        "dua_musa_faqir" to DuaText("Addu'ar Musa (AS) don Taimako", "Ya Ubangijina, hakika ni mai buqata ne ga duk abin da Ka saukar zuwa gare ni na alheri.", "Neman arziki da kyau - addu'ar Musa (AS) a Madyan.", "Bayan wannan addu'ar, Allah ya ba Musa (AS) gida, aiki da mata."),
        "dua_ayyub" to DuaText("Addu'ar Ayyub (AS) a cikin rashin lafiya", "(Ya Ubangijina) cũta ta shãfe ni, kuma Kai ne Mafi rahamar mãsu rahama.", "Cikin rashin lafiya da wahala.", "Allah ya yaye wa Ayyub (AS) wahala."),
        "dua_husn_khatimah" to DuaText("Ka mutu a matsayin Musulmi (Yusuf AS)", "Mahaliccin sammai da ƙasa, Kai ne Majiɓincina a duniya da Lahira. Ka sanya ni in mutu ina musulmi, kuma ka hada ni da salihai.", "Addu'a don kyakkyawan sakamako.", "Addu'ar Annabi Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Gudun Hijira daga Wasuwar Shaidanun", "Ya Ubangijina, ina neman tsarinka daga fizgar shaidanu, kuma ina neman tsarinka, ya Ubangiji, kada su kusance ni.", "Ku gudu daga waswasi na shaidan.", "Addu'ar neman tsari daga Qur'ani."),
        "dua_bad_character" to DuaText("Gudu daga Mummunan Hali", "Ya Allah ina neman tsarinka daga munanan halaye da munanan ayyuka da munanan sha'awa.", "Ka guje wa munanan halaye, ayyuka da sha'awa.", "Addu'ar tsari daga Annabi ﷺ."),
        "dua_zawal_nimah" to DuaText("Masoya Daga Rashin Albarka", "Ya Allah ina neman tsarinka daga bata ni'imominka, da canza rayuwarka, da azabar ka kwatsam, da dukkan bacin ranka.", "Ka nisanci rasa albarka da bala'i kwatsam.", "Addu'ar Annabi ﷺ."),
        "dua_useless_knowledge" to DuaText("Gudu daga Ilimi mara amfani", "Ya Allah ina neman tsarinka daga ilimin da ba ya amfani, da zuciyar da ba ta tsoro, da ruhin da ba ta koshi, da addu'ar da ba a amsawa.", "Ka nisanci ilimi na banza da zuciya marar tsoron Allah.", "Addu'ar tsari daga Annabi ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Ilimi Mai Amfani & Halal Rizq", "Ya Allah ina rokonka ilimi mai amfani, arziki mai tsafta da ayyuka karbabbe.", "Bayan sallar asuba.", "Annabi ﷺ ya fadi haka bayan sallamar asubahi."),
        "dua_leprosy_diseases" to DuaText("Gudun hijira daga Mummunan Cututtuka", "Ya Allah ina neman tsarinka daga vitiligo, hauka, kuturu da dukkan muggan cututtuka.", "Kariya daga cututtuka masu tsanani.", "Addu'ar Sunnah domin kiyaye lafiya."),
        "dua_fear_people" to DuaText("Tsoron Makiya ko Azzalumai", "Ya Allah mun dora ka a gaba garesu, kuma muna neman tsarinka daga sharrinsu.", "Lokacin tsoron cutar da mutane ko mutum.", "Annabi ﷺ ya faxi haka a lokacin da ya ji tsoron mutane."),
        "dua_shirk_protection" to DuaText("Kariya daga Boyayyen Shirka", "Ya Allah ina neman tsarinka da in hada wani abu da kai na sane, kuma ina neman gafararka akan abinda nake aikatawa ba tare da sani ba.", "Domin tsira daga bayyanar da shirka da boye.", "6oyayyar shirka ta fi ruguza tururuwa."),
        "dua_rain" to DuaText("Lokacin Ruwan Ruwa", "Ya Allah ka saukar da ruwan sama mai albarka.", "Lokacin da aka yi ruwan sama.", "Ruwan sama lokaci ne da ake karbar addu'a."),
        "dua_after_rain" to DuaText("Bayan Ruwan sama", "An yi mana ruwan sama da falalar Allah da rahamarSa.", "Bayan ruwan sama.", "Wanda ya fadi haka ya kasance mai imani da Allah."),
        "dua_istisqa" to DuaText("Neman ruwan sama (Istisqa)", "Ya Allah ka saukar mana da ruwan sama (sau uku).", "Lokacin da babu ruwan sama.", "Annabi ﷺ yayi wannan addu'ar a cikin hudubar juma'a kuma aka yi ruwan sama."),
        "dua_heavy_rain" to DuaText("Ruwan sama mai yawa", "Ya Allah (ka sa ta fadi) a kusa da mu ba akan mu ba.", "Lokacin da ruwa ya yi yawa.", "Gizagizai sun tafi ta cikin addu'ar Annabi ﷺ."),
        "dua_wind" to DuaText("Lokacin da iska ke kadawa", "Ya Allah ina rokonka alherin sa, da alherin da ke cikinsa da na abin da aka aiko shi da shi, kuma ina neman tsarinka daga sharrinsa, da sharrin da ke cikinsa da sharrin abin da aka aiko shi da shi.", "Lokacin da iska mai karfi ko hadari ke kadawa.", "Annabi ﷺ yayi wannan addu'ar a lokacin hadari."),
        "dua_thunder" to DuaText("Jin Tsawa", "Tsarki ya tabbata ga wanda tsawa ta yi tasbihi da godiyarSa, da mala'iku saboda tsoronsa.", "A kan jin aradu - al'adar Abdullah ibn az-Zubayr (RA).", "An karbo daga suratun Ra'ad (13:13)."),
        "dua_new_moon" to DuaText("Ganin Sabon Wata", "Ya Allah ka sa wannan wata ya haskaka mana da albarka da imani da aminci da Musulunci. (Ya wata,) Ubangijina kuma Ubangijinku ne Allah.", "A kan ganin sabon wata.", "Addu'ar Sunnah na kowane sabon wata."),
        "dua_janaza_adult" to DuaText("Sallar Janaza (Babban)", "Ya Allah ka gafartawa rayayyummu da matattunmu, wadanda suke da wadanda ba su nan, da samarinmu da manyanmu, maza da matanmu. Ya Allah duk wanda ka raya daga cikin mu, ka raya shi akan musulunci, kuma duk wanda ka kashe daga cikin mu, ka kashe shi akan imani.", "Bayan takbir na uku na sallar gawa.", "Addu'ar Sunnah ga babban mamaci."),
        "dua_janaza_child" to DuaText("Sallar Janaza (Yaro)", "Ya Allah Ka sanya shi ya zama mafari (kuma mai masaukin baki) garemu, ka sanya shi lada da taska a gare mu, kuma ka sanya shi mai ceto gare mu wanda cetonsa karbabbe ne.", "A cikin Sallar Jana'izar Yaro (Ga yarinya ta ce 'Ijjal').", "Addu'ar Sunnah da Hanafiyya suke yi."),
        "dua_mayyit_awf" to DuaText("Cikakken Addu'a ga Marigayi", "Ya Allah ka gafarta masa, ka yi masa rahama, ka ba shi lafiya, ka gafarta masa. Ka sanya liyafarsa ta zama abin daraja, ka kyautata masa kabarinsa, ka wanke shi da ruwa, da dusar ƙanƙara da ƙanƙara, ka tsarkake shi daga zunubai, kamar yadda ake tsarkake farin tufa daga ƙazanta.", "A cikin sallar jana'iza ko na mamaci.", "Awf bn Malik (RA) ya yi fatan cewa ya kasance wannan mamacin."),
        "dua_visiting_graves" to DuaText("Ziyarar Kaburbura", "Assalamu alaikum yaku ma'abota wadannan gidaje muminai da musulmai. Mu ma in Allah ya yarda za mu hada ku. Ina rokon Allah ya jikan mu da ku.", "Lokacin shiga makabarta.", "Ziyarar kaburbura tana tunatar da mutum mutuwa da Lahira."),
        "dua_closing_eyes" to DuaText("Bayan Rufe Idanun Marigayi", "Ya Allah ka gafartawa (suna) ka daukaka darajarsa a cikin shiryayyu, ka kasance magadansa cikin wadanda ya bari. Ka gafarta mana, shi da shi, Ya Ubangijin talikai; Ka yalwata kabarinsa, ka cika shi da haske.", "Lokacin rufe idon mamaci (ya ambaci sunansa).", "Annabi ﷺ yayi wannan addu'ar ga Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Ta'aziya (Ta'aziya)", "Lalle ne Allah ne da abin da Ya riƙi, kuma Shi ne da abin da Ya bãyar, kuma kõwane abu a wurinSa akwai ajali ambatacce, sabõda haka ka yi haƙuri, kuma ka yi fatan ijãra.", "Ta'aziyya ga dangi bayan rasuwa.", "Annabi ﷺ ya aiko da wannan sakon zuwa ga diyarsa."),
        "dua_placing_in_grave" to DuaText("Sanya mamaci a cikin Qabari", "Da sunan Allah kuma bisa tafarkin Manzon Allah ﷺ.", "Lokacin saukar da mamaci zuwa cikin kabari.", "Addu'ar binnewa Sunnah."),
        "dua_sneezing" to DuaText("atishawa", "Dukkan godiya ta tabbata ga Allah. - Allah Ya yi muku rahama. - Allah Ya yi muku jagora, Ya daidaita al'amuran ku.", "Akan atishawa; mai saurare yace 'Yarhamukallah', sai wanda yayi atishawa ya amsa.", "Yana daga cikin hakkokin musulmi akan wani musulmi."),
        "dua_toilet_enter" to DuaText("Shiga bandaki", "Da sunan Allah. Ya Allah ina neman tsarinka daga aljani najasa namiji da mace.", "Kafin shiga bandaki da kafar hagu.", "Bismillah ta zama allo tsakanin aljani da mutum."),
        "dua_toilet_exit" to DuaText("Barin bandaki", "(Ya Allah,) Ina neman gafararKa.", "Lokacin fita daga bayan gida da ƙafar dama.", "Annabi ﷺ ya fadi haka akan fita bayan gida."),
        "dua_thanking" to DuaText("Godiya ga Wani", "Allah Ya saka muku da alheri.", "Lokacin da wani yayi maka alheri.", "Duk wanda ya fadi haka ya mika godiyarsa matuka."),
        "dua_love_for_allah" to DuaText("Lokacin da Wani Yace 'Ina Sonki Don Allah'", "Shi (Allah) wanda kuke so na saboda shi, ya so ku.", "Lokacin da wani ya ce 'Ina son ku saboda Allah'.", "Sunnah ta amsa soyayya don Allah."),
        "dua_seeing_muslim_smile" to DuaText("Wassalamu'alaikum", "Assalamu alaikum, da rahamar Allah da albarkarSa.", "Lokacin saduwa da musulmi.", "Yin sallama cikakkiya yana samun kyawawan ayyuka talatin."),
        "dua_dressing" to DuaText("Yin Tufafi", "Dukkan godiya ta tabbata ga Allah wanda ya tufatar da ni da wannan, kuma Ya azurta ni da ita ba tare da wani karfi ko karfi daga wajena ba.", "Lokacin yin sutura.", "Bisharar gafarar zunubai da suka gabata."),
    )
}
